type RouteSeed = Omit<RouteFamily, "suggestedDays" | "stops" | "connections" | "sourceLinks" | "reviewedAt"> & {
  days: [number, number, number];
  stops: Array<[string, string, [number, number], number, string]>;
  sources?: RouteFamily["sourceLinks"];
};

const seededRoute = ({ days, stops, sources, ...route }: RouteSeed): RouteFamily => ({
  ...route,
  suggestedDays: { min: days[0], ideal: days[1], max: days[2] },
  stops: stops.map(([name, country, coordinates, minimumNights, reason]) => ({ name, country, coordinates, minimumNights, reason })),
  connections: [],
  sourceLinks: sources ?? [],
  reviewedAt: "2026-08-09",
});

